#!/bin/bash
# Fails if the committed Xcode project has drifted from project.yml.
#
# The project is generated by XcodeGen but committed (see .gitignore), so the two
# can silently disagree if someone edits project.yml without regenerating, or
# edits build settings in Xcode's UI instead of in project.yml. Run this before
# pushing a project.yml change.
set -e
cd "$(dirname "$0")/.."

if ! command -v xcodegen > /dev/null 2>&1; then
    echo "❌ xcodegen not installed — brew install xcodegen"
    exit 1
fi

xcodegen --quiet
if git diff --quiet HEAD -- HomeDashboardTV.xcodeproj HomeDashboardTV/Info.plist \
   && [ -z "$(git status --porcelain --untracked-files=all -- HomeDashboardTV.xcodeproj HomeDashboardTV/Info.plist)" ]; then
    echo "✅ Xcode project matches project.yml."
else
    echo "❌ The committed Xcode project is out of date with project.yml."
    echo "   Regenerating changed these files:"
    git diff --stat HEAD -- HomeDashboardTV.xcodeproj HomeDashboardTV/Info.plist | sed 's/^/     /'
    git status --porcelain --untracked-files=all -- HomeDashboardTV.xcodeproj HomeDashboardTV/Info.plist | sed 's/^/     /'
    echo "   Commit the regenerated project, or revert stray edits made in Xcode's UI."
    exit 1
fi
